    ledger :: open_ledger()
    ledger.prepare()          // stage the transfer (may park; unwinds normally if cancelled)
    #Shield {                 // once we start committing, finish it
        ledger.write_row()    // wait point INSIDE shield: completes, does NOT unwind
        ledger.write_row()
        ledger.commit()       // prints "committed" atomically
    }                         // cancel that arrived during the shield unwinds HERE
    return 500
